python3 - <<'EOF'
import json, subprocess

def call(endpoint, **params):
    params['token'] = '<TOKEN>'
    args = ['curl','-s','-X','POST',f'https://slack.com/api/{endpoint}','-H','Authorization: Bearer <TOKEN>']
    for k,v in params.items():
        args += ['-d', f'{k}={v}']
    return json.load(subprocess.run(args, capture_output=True, text=True).stdout)

cursor = ''
while True:
    d = call('conversations.list', exclude_archived='false', types='public_channel,private_channel', limit='1000', cursor=cursor)
    if not d.get('ok'):
        print('ERR', d); break
    for c in d.get('channels', []):
        print(c['id'], c.get('name'), 'created', c.get('created'), 'archived' if c.get('is_archived') else 'active')
    cursor = d.get('response_metadata',{}).get('next_cursor','')
    if not cursor:
        break
EOF

